INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Projektorganisation ein zentraler Bestandteil des Projektmanagements?', 2, '[{"text": "Ja", "correct": true, "because": "Definiert Struktur und Rollen"}, {"text": "Nein", "correct": false, "because": "Sie ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt die Projektorganisation?', 3, '[{"text": "Effektive Zusammenarbeit ermöglichen", "correct": true, "because": "Fördert Koordination"}, {"text": "Kosten direkt senken", "correct": false, "because": "Nebenaspekt"}, {"text": "Zeitplan erstellen", "correct": false, "because": "Planungsaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Projektorganisation definiert Verantwortlichkeiten. b) Sie wird nur in der Durchführung genutzt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, alle Phasen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Projektorganisation?', 4, '[{"text": "Rollen", "correct": true, "because": "Definieren Zuständigkeiten"}, {"text": "Unklare Struktur", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Kommunikationswege", "correct": true, "because": "Fördern Austausch"}, {"text": "Prozesse", "correct": true, "because": "Regeln Abläufe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne Organisation erfolgreich sein?', 2, '[{"text": "Nein", "correct": true, "because": "Struktur und Rollen fehlen"}, {"text": "Ja", "correct": false, "because": "Chaos droht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Projektorganisation?', 3, '[{"text": "Koordination der Beteiligten sichern", "correct": true, "because": "Fördert Zusammenarbeit"}, {"text": "Projektziele neu definieren", "correct": false, "because": "Initiierungsschritt"}, {"text": "Kosten direkt überwachen", "correct": false, "because": "Controlling-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Projektorganisation nur für große Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte brauchen sie"}, {"text": "Ja", "correct": false, "because": "Universelle Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe gehört zur Projektorganisation?', 3, '[{"text": "Rollen und Verantwortlichkeiten festlegen", "correct": true, "because": "Definiert Zuständigkeiten"}, {"text": "Fortschritt direkt messen", "correct": false, "because": "Controlling-Aufgabe"}, {"text": "Zeitplan erstellen", "correct": false, "because": "Planungsaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Projektorganisation fördert Kommunikation. b) Sie ist immer unveränderlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, anpassbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Projektorganisation?', 3, '[{"text": "Unklare Zuständigkeiten", "correct": true, "because": "Fehlende Struktur"}, {"text": "Projekt wird schneller", "correct": false, "because": "Eher Verzögerung"}, {"text": "Kosten sinken", "correct": false, "because": "Ineffizienz möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Projektorganisation ohne Rollen definiert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Rollen sind Kern"}, {"text": "Ja", "correct": false, "because": "Unklarheit droht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine Projektorganisation?', 3, '[{"text": "Projektleiter koordiniert Team", "correct": true, "because": "Klar und strukturiert"}, {"text": "Irgendwas machen", "correct": false, "because": "Zu vage"}, {"text": "Team soll arbeiten", "correct": false, "because": "Keine Organisation"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Projektorganisation nur für den Projektstart relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt für alle Phasen"}, {"text": "Ja", "correct": false, "because": "Projektweite Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat eine Projektorganisation?', 4, '[{"text": "Definierte Rollen", "correct": true, "because": "Fördern Klarheit"}, {"text": "Unklare Prozesse", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Kommunikationsstruktur", "correct": true, "because": "Fördert Austausch"}, {"text": "Verantwortlichkeiten", "correct": true, "because": "Regeln Zuständigkeiten"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Projektorganisation dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachweis erforderlich"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug unterstützt die Projektorganisation?', 3, '[{"text": "Organigramm", "correct": true, "because": "Zeigt Rollenstruktur"}, {"text": "Keine Dokumentation", "correct": false, "because": "Fehlt Übersicht"}, {"text": "Zufällige Notizen", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Projektorganisation ohne Kommunikation funktionieren?', 2, '[{"text": "Nein", "correct": true, "because": "Austausch essenziell"}, {"text": "Ja", "correct": false, "because": "Unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert die Projektorganisation?', 3, '[{"text": "Unklare Rollen", "correct": true, "because": "Verhindern Struktur"}, {"text": "Klarer Zeitplan", "correct": false, "because": "Fördert Ablauf"}, {"text": "Gute Kommunikation", "correct": false, "because": "Unterstützt Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Projektorganisation steigert Effizienz. b) Sie ist nur für IT-Projekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, breit anwendbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen der Projektorganisation?', 3, '[{"text": "Klare Verantwortungsbereiche", "correct": true, "because": "Fördert Koordination"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Struktur", "correct": false, "because": "Fördert Ordnung"}]');
